    def add_summary_card(self, kicker, metric, support=""):
        # Check if card with same kicker already exists to avoid duplicates
        for card in self.summary_cards:
            if card['kicker'] == kicker:
                card['metric'] = metric
                card['support'] = support
                return
        self.summary_cards.append({
            'kicker': kicker,
            'metric': metric,
            'support': support
        })

