    def set_date_time_directory(self, _date, _results_dir_name):
        # Format the date time to make it safe for directory names (replace colons/spaces/slashes with hyphens)
        date_str = _date if _date else self.date
        clean_date = date_str.replace(" ", "-").replace(":", "-").replace("/", "-")
        
        # Combine date/time and results directory name to form a unique directory name
        unique_dir_name = f"{clean_date}_{_results_dir_name}"
        self.date_time_directory = unique_dir_name
        if not self.path_date_time:
            self.path_date_time = os.path.join(self.path, unique_dir_name)

    def build_date_time_directory(self):
        if self.path_date_time and not os.path.exists(self.path_date_time):
            try:
                os.makedirs(self.path_date_time)
            except Exception as e:
                logger.warning(f"Could not create path_date_time directory {self.path_date_time}: {e}")

    def build_log_directory(self):
        if self.path_date_time:
            self.log_directory = os.path.join(self.path_date_time, "logs")
            if not os.path.exists(self.log_directory):
                try:
                    os.makedirs(self.log_directory)
                except Exception as e:
                    logger.warning(f"Could not create log directory {self.log_directory}: {e}")

