    def __getattr__(self, name):
        # Graceful fallback for any missing method to prevent crashes in caller scripts
        logger.warning(f"lf_report: method '{name}' called but not explicitly implemented. Using dummy fallback.")
        def dummy(*args, **kwargs):
            return None
        return dummy

