    def move_graph_image(self):
        # No-op: graph images are embedded as base64 directly into the report
        # HTML (see the chart-rendering loop that builds js_charts_code), so a
        # standalone copy in the report folder is never read back from disk.
        # generate_html() still finds the original file next to where it was
        # rendered (self.graph_image keeps that path) when it base64-encodes it.
        pass

